CREATE VIEW mart_recommendation_v4 AS WITH rule_weights AS (SELECT max(CASE  WHEN ((RuleValue = 'Open World')) THEN (RuleWeight) ELSE NULL END) AS open_world_weight, max(CASE  WHEN ((RuleValue = 'Third Person')) THEN (RuleWeight) ELSE NULL END) AS third_person_weight, max(CASE  WHEN ((RuleValue = 'Action')) THEN (RuleWeight) ELSE NULL END) AS action_weight, max(CASE  WHEN ((RuleValue = 'Role-playing (RPG)')) THEN (RuleWeight) ELSE NULL END) AS rpg_weight, max(CASE  WHEN ((RuleValue = 'Shooter')) THEN (RuleWeight) ELSE NULL END) AS shooter_weight, max(CASE  WHEN ((RuleValue = 'SHMUP')) THEN (RuleWeight) ELSE NULL END) AS shmup_penalty, max(CASE  WHEN ((RuleValue = 'Souls-like')) THEN (RuleWeight) ELSE NULL END) AS soulslike_penalty, max(CASE  WHEN ((RuleValue = 'Difficulty Mitigation')) THEN (RuleWeight) ELSE NULL END) AS mitigation_bonus FROM PreferenceRule), scored AS (SELECT rb.*, COALESCE(gpp.SpecialAccessoryRequired, CAST('f' AS BOOLEAN)) AS SpecialAccessoryRequired, COALESCE(gpp.ControlSchemeRisk, 'Unknown') AS ControlSchemeRisk, COALESCE(gpp.RhythmFlag, CAST('f' AS BOOLEAN)) AS RhythmFlag, COALESCE(gpp.SHMUPFlag, CAST('f' AS BOOLEAN)) AS SHMUPFlag, COALESCE(gpp.SoulslikeFlag, CAST('f' AS BOOLEAN)) AS SoulslikeFlag, COALESCE(gpp.MitigationAvailable, CAST('f' AS BOOLEAN)) AS MitigationAvailable, gpp.PlayabilityNotes, CASE  WHEN ((rb.Themes ~~* '%Open World%')) THEN (rw.open_world_weight) ELSE 0 END AS open_world_score, CASE  WHEN ((rb.Perspectives ~~* '%Third Person%')) THEN (rw.third_person_weight) ELSE 0 END AS third_person_score, CASE  WHEN ((rb.Themes ~~* '%Action%')) THEN (rw.action_weight) ELSE 0 END AS action_score, CASE  WHEN ((rb.Genres ~~* '%Role-playing (RPG)%')) THEN (rw.rpg_weight) ELSE 0 END AS rpg_score, CASE  WHEN ((rb.Genres ~~* '%Shooter%')) THEN (rw.shooter_weight) ELSE 0 END AS shooter_score, ((CASE  WHEN ((gpp.SHMUPFlag = CAST('t' AS BOOLEAN))) THEN (rw.shmup_penalty) ELSE 0 END + CASE  WHEN ((gpp.SoulslikeFlag = CAST('t' AS BOOLEAN))) THEN (rw.soulslike_penalty) ELSE 0 END) + CASE  WHEN ((gpp.MitigationAvailable = CAST('t' AS BOOLEAN))) THEN (rw.mitigation_bonus) ELSE 0 END) AS playability_adjustment FROM mart_recommendation_base AS rb LEFT JOIN GamePlayabilityProfile AS gpp ON ((gpp.GameID = rb.GameID)) , rule_weights AS rw)SELECT *, ((((open_world_score + third_person_score) + action_score) + rpg_score) + shooter_score) AS explicit_preference_score, CASE  WHEN (((SpecialAccessoryRequired = CAST('t' AS BOOLEAN)) OR (RhythmFlag = CAST('t' AS BOOLEAN)))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS hard_exclusion_flag, CASE  WHEN ((SpecialAccessoryRequired = CAST('t' AS BOOLEAN))) THEN ('Special accessory required') WHEN ((RhythmFlag = CAST('t' AS BOOLEAN))) THEN ('Rhythm-focused gameplay') ELSE NULL END AS exclusion_reason, CASE  WHEN (((SpecialAccessoryRequired = CAST('t' AS BOOLEAN)) OR (RhythmFlag = CAST('t' AS BOOLEAN)))) THEN (NULL) ELSE (((((open_world_score + third_person_score) + action_score) + rpg_score) + shooter_score) + playability_adjustment) END AS adjusted_preference_score FROM scored;
